def intersect(a, b):
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            if not out or out[-1] != a[i]:
                out.append(a[i])
            i, j = i + 1, j + 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return out

print(intersect([1, 2, 2, 4, 9], [2, 2, 4, 5, 9]))

def dedupe_sorted(lst):
    if not lst:
        return 0
    write = 1
    for read in range(1, len(lst)):
        if lst[read] != lst[write - 1]:
            lst[write] = lst[read]
            write += 1
    return write

