def stats(nums):
    if not nums:
        return {'count': 0, 'sum': 0, 'avg': 0, 'min': None, 'max': None}
    total = sum(nums)
    return {'count': len(nums), 'sum': total, 'avg': round(total / len(nums), 2), 'min': min(nums), 'max': max(nums)}

print(stats([2, 3, 4, 5, 6, 7]))
print(stats([]))

def dedupe(items):
    seen, out = set(), []
    for x in items:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

print(dedupe([3, 1, 3, 2, 1, 4]))

def flatten(data):
    out = []
    for item in data:
        if isinstance(item, (list, tuple)):
            out.extend(flatten(item))
        else:
            out.append(item)
    return out

