def classify(marks):
    def grade(m):
        if m >= 90:
            return 'A'
        if m >= 75:
            return 'B'
        if m >= 60:
            return 'C'
        if m >= 40:
            return 'D'
        return 'F'

    passed, failed, counts = [], [], {}
    for m in marks:
        (passed if m >= 40 else failed).append(m)
        g = grade(m)
        counts[g] = counts.get(g, 0) + 1
    return passed, failed, counts

p, f, c = classify([78, 92, 45, 88, 61, 33])
print(len(p), len(f), dict(sorted(c.items())))

