import json, logging, os, tempfile
from datetime import date

logging.basicConfig(level=logging.INFO, format='%(levelname)s %(message)s')

PRIORITIES = ('low', 'medium', 'high')


def validate(task):
    if not task.get('title', '').strip():
        raise ValueError('title required')
    if task.get('priority', 'medium') not in PRIORITIES:
        raise ValueError(f'priority must be one of {PRIORITIES}')
    if 'due' in task:
        date.fromisoformat(task['due'])
    return {**task, 'done': bool(task.get('done', False))}


def save(tasks, path):
    d = os.path.dirname(path) or '.'
    fd, tmp = tempfile.mkstemp(dir=d, suffix='.tmp')
    try:
        with os.fdopen(fd, 'w') as f:
            json.dump(tasks, f)
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            os.remove(tmp)
    return path


def load(path):
    if not os.path.exists(path):
        return []
    try:
        with open(path) as f:
            return json.load(f)
    except json.JSONDecodeError:
        logging.error('corrupt task file %s — starting empty (backup kept)', path)
        os.replace(path, path + '.corrupt')
        return []


def add(tasks, **fields):
    tasks.append(validate(fields))
    return tasks[-1]


def update(tasks, index, **fields):
    tasks[index] = validate({**tasks[index], **fields})
    return tasks[index]


def delete(tasks, index):
    return tasks[:index] + tasks[index + 1:]


def visible(tasks, status='all', tag=None):
    rows = [t for t in tasks if status == 'all' or t['done'] == (status == 'done')]
    if tag:
        rows = [t for t in rows if tag in t.get('tags', [])]
    return sorted(rows, key=lambda t: (t['done'], -PRIORITIES.index(t['priority']), t.get('due', '9999-12-31'), t['title']))


def summary(tasks):
    done = sum(1 for t in tasks if t['done'])
    return {'total': len(tasks), 'done': done, 'open': len(tasks) - done,
            'high_open': sum(1 for t in tasks if t['priority'] == 'high' and not t['done'])}


path = os.path.join(tempfile.gettempdir(), 'tasks_demo.json')
tasks = load(path)
add(tasks, title='Fix retry logic', priority='high', due='2026-09-30', tags=['api'])
add(tasks, title='Write runbook', priority='medium', tags=['docs'])
update(tasks, 1, done=True)
print(save(tasks, path))
print(visible(tasks, status='open'))
print(summary(tasks))
print(visible(tasks, tag='api')[0]['title'])
try:
    add(tasks, title='   ', priority='urgent')
except ValueError as e:
    print('rejected:', e)
